import {DAYS} from '../../server/programmes/schema.mjs';
const common={title:'Example programme',summary:'Synthetic fixture for validation.',focus:['Energy','Enjoyment','Recovery'],habits:[{id:'water',label:'Water',target:'With meals'},{id:'sleep',label:'Sleep',target:'A steady routine'}],coach_notes:['Coach to review before sharing.']};
export function nutritionFixture(){return structuredClone({...common,ingredients:Array.from({length:8},(_,i)=>({id:`food${i}`,name:`Example food ${i}`,unit:'g'})),recipes:Array.from({length:14},(_,i)=>({id:`meal${i}`,title:`Example meal ${i}`,visual:'bowl',minutes:15,ingredients:[{id:`food${i%8}`,quantity:100}],steps:['Prepare the ingredients.','Cook and serve.'],tip:'Adjust to appetite.'})),week:DAYS.map((day,i)=>({day,focus:'Fuel and recover',breakfast:'meal7',lunch:'meal8',dinner:`meal${i}`,snack:'meal9',timing:'Eat around training.'})),swaps:[{from:'meal0',to:'meal10',reason:'More variety'},{from:'meal1',to:'meal11',reason:'More variety'},{from:'meal2',to:'meal12',reason:'More variety'}],prep:['Prepare lunch boxes.','Store chilled foods safely.']});}
export function gymFixture(){return structuredClone({...common,sessions:[{id:'session_a',title:'Controlled basics',focus:'full',minutes:30,warmup:['Walk and mobilise.','Rehearse movements.'],exercises:['squat','push','core'].map((pattern,i)=>({id:`exercise${i}`,name:`Example ${pattern}`,pattern,sets:2,reps:'8 controlled repetitions',rest_seconds:60,effort:'Leave a few repetitions in reserve',cue:'Move with control.',easier:'Reduce range with coach guidance.',equipment:'Bodyweight'})),cooldown:['Walk and recover.']}],week:DAYS.map(day=>({day,session_id:day==='Monday'?'session_a':'',focus:day==='Monday'?'Move with control':'Rest or existing sport'})),progression:[1,2,3,4].map(week=>({week,focus:'Progress only with good form and recovery.'}))});}
